export function applyProp(o){let p=PROPS[o.type];if(!p)return o;[o.name,o.w,o.d,o.height,o.color]=p;o.blocksSight=['house','tent','shelf','statue'].includes(o.type);o.blocking=!['flowers','grass','mushroom','rug','bridge','campfire'].includes(o.type);o.shadow=!['rug','pond','bridge'].includes(o.type);if(['stairs','platform','balcony',...ROOFS].includes(o.type)){o.blocking=false;o.blocksSight=false;if(o.type==='stairs')o.rise=1;}if(o.type.startsWith('fx_')){let kind=o.type.slice(3);o.blocking=false;o.blocksSight=false;o.shadow=false;o.effect={kind,color:FX[kind].color,size:1,speed:1,density:1};if(kind==='fire')o.light={radius:6,power:.8,color:'#ffbe70'};}if(o.type==='campfire'){o.effect={kind:'fire',color:'#ffac43',size:1,speed:1,density:1};}if(ASSETS[o.type]){o.blocksSight=false;o.color=null;if(ASSETS[o.type].source==='lantern'){o.light={radius:6,power:.7,color:'#ffd294'};o.effect={kind:'fire',size:.18,color:'#ffb854',density:.5};o.blocking=false}}if(o.type==='campfire')o.light={radius:7,power:1,color:'#ffc178'};return o}
