// One-time migration: preserve every legacy floor as a distinct editable map.
export function upgradeBlockWorld(world){if(world.blockWorldRevision>=1){for(let m of world.maps)V.prepareBlocks(m);return 0}let originals=[...world.maps],routes=new Map(),count=0;
 for(let m of originals){let levels=new Set([0,...m.objects.map(levelOf),...(m.effects||[]).map(e=>e.level||0)]);for(let o of m.objects)if(o.type==='stairs')levels.add(levelOf(o)+(o.rise||1));let originalObjects=[...m.objects],originalEffects=[...(m.effects||[])];for(let level of [...levels].sort((a,b)=>a-b)){let target=m;if(level){let id=m.id+'-room-'+level;while(world.maps.some(t=>t.id===id))id+='x';target={...structuredClone(m),id,name:m.name+' · Annexe '+level,objects:[],effects:[],terrain:{},blocks:{},floor:{},fog:[],extensions:[],combat:null};world.maps.push(target);count++}routes.set(m.id+':'+level,target);target.objects=originalObjects.filter(o=>levelOf(o)===level);target.effects=originalEffects.filter(e=>(e.level||0)===level);target.editLevel=0;target.showUpper=false;delete target.transitionLevel;V.prepareBlocks(target);}
 for(let o of originalObjects)if(o.type==='stairs'){let ends=stairEnds(o),bottom=routes.get(m.id+':'+ends.bottom.level),top=routes.get(m.id+':'+ends.top.level);if(bottom&&top){for(let [from,to,entry,exit]of [[bottom,top,ends.bottom,ends.top],[top,bottom,ends.top,ends.bottom]]){let x=clamp(entry.x,0,from.width-1),y=clamp(entry.y,0,from.height-1),portal=newObject('portal',x,y,o.id+'-passage-'+from.id);portal.name='Vers '+to.name;portal.target=to.id;portal.spawnX=clamp(exit.x,0,to.width-1);portal.spawnY=clamp(exit.y,0,to.height-1);portal.spawnLevel=0;portal.level=0;from.objects.push(portal)}}}
 }
 for(let m of world.maps){if(m.combat){m.combat.ids=m.combat.ids.filter(id=>m.objects.some(o=>o.id===id));if(!m.combat.ids.length)m.combat.active=false}for(let o of m.objects){if(o.type==='portal'&&o.target){let target=routes.get(o.target+':'+(o.spawnLevel||0));if(target)o.target=target.id;o.spawnLevel=0}o.level=0;delete o.travelZ;if(character(o))o.voxelZ=V.blockHeight(m,o.x,o.y)}for(let e of m.effects||[])e.level=0;}world.blockWorldRevision=1;return count}
export function blockPlacementError(map,x,y,z,material,height=1){if(![x,y,z,height].every(Number.isFinite)||!activeCell(map,x,y)||z<V.MIN_BLOCK_HEIGHT||z+(material?height:0)>V.MAX_BLOCK_HEIGHT||z>=V.MAX_BLOCK_HEIGHT)return 'Hors des limites de construction.';if(material&&V.BLOCKS[material]?.solid&&map.objects.some(o=>character(o)&&actorVolumes(o,map).some(v=>x<v.x+1&&x+1>v.x&&y<v.y+1&&y+1>v.y&&z+height>v.baseZ&&z<v.baseZ+v.height)))return 'Un personnage occupe cet emplacement.';return null}

export const eyeHeight=o=>clamp(o?.vision?.eye??((o?.height||1.8)*(o?.scale||1)*.85),.25,12);
export function sightHit(map,a,b,objects,ignore,z0,z1){let nearest=null,length=Math.hypot(b.x-a.x,b.y-a.y);for(let o of nearObstacles(objects,a,b)){let hit=rayHit(a,b,[o],ignore);if(!hit)continue;let distance=length*hit.t,z=z0+(z1-z0)*hit.t,bottom=elevation(o,map);if(z<bottom||z>bottom+(o.height||1.6))continue;if(!nearest||distance<nearest.distance)nearest={...hit,distance}}return nearest}

export function displayBars(o){let bars=[];if(o.showHealth)bars.push({name:'PV',value:clamp(o.hp??o.max??20,0,Math.max(1,o.max||20)),max:Math.max(1,o.max||20),color:'#a6d192'});for(let b of o.bars||[])if(b.visible!==false){let max=Math.max(1,Number(b.max)||1);bars.push({name:String(b.name||'Ressource'),value:clamp(Number(b.value)||0,0,max),max,color:/^#[0-9a-f]{6}$/i.test(b.color)?b.color:'#78b7db'})}return bars}

// Read saved worlds before running migrations. Preserve damaged data before any fallback save.
export function readSavedWorld(storage){
 let raw=null;
 try{
  raw=storage.getItem('brumes-v4');
  let world=raw?JSON.parse(raw):migrate(JSON.parse(storage.getItem('brumes-v1')));
  if(!world||world.version!==4||!Array.isArray(world.maps)||!world.maps.length)throw Error('Structure du monde invalide');
  const ids=new Set(),record=v=>!!v&&typeof v==='object'&&!Array.isArray(v);
  if(world.schematics!==undefined&&(!Array.isArray(world.schematics)||world.schematics.some(s=>!record(s)||!Array.isArray(s.objects))))throw Error('Schémas invalides');
  if(world.builder!==undefined&&(!record(world.builder)||!Array.isArray(world.builder.slots)||world.builder.slots.length!==9||world.builder.slots.some(s=>!record(s))))throw Error('Inventaire invalide');
  for(const m of world.maps){
   if(!record(m)||typeof m.id!=='string'||ids.has(m.id)||!Number.isInteger(m.width)||!Number.isInteger(m.height)||m.width<1||m.height<1||m.width>MAX_MAP||m.height>MAX_MAP||!Array.isArray(m.objects))throw Error('Carte invalide');
   ids.add(m.id);
   const defaults=newMap(m.id,String(m.name||'Carte'),m.width,m.height),objectIds=new Set();
   for(const o of m.objects){
    if(!record(o)||typeof o.id!=='string'||objectIds.has(o.id)||typeof o.type!=='string'||!Number.isFinite(o.x)||!Number.isFinite(o.y))throw Error('Élément invalide');
    objectIds.add(o.id);o.name=String(o.name||TYPES[o.type]||'Élément');
    if(o.bars!==undefined&&(!Array.isArray(o.bars)||o.bars.some(b=>!record(b))))throw Error('Barres invalides');
   }
   for(const key of ['chunks','groups','fog']){if(m[key]===undefined)m[key]=defaults[key];if(!Array.isArray(m[key]))throw Error('Liste de carte invalide')}
   if(m.groups.some(g=>!record(g)||typeof g.id!=='string')||m.chunks.some(k=>typeof k!=='string')||m.fog.some(k=>typeof k!=='string'))throw Error('Calques invalides');
   for(const key of ['floor','lighting','camera']){if(m[key]===undefined)m[key]=defaults[key];if(!record(m[key]))throw Error('Paramètres de carte invalides')}
   m.camera={...defaults.camera,...m.camera};m.lighting={...defaults.lighting,...m.lighting};
   for(const key of ['angle','tilt','zoom','panX','panY'])if(!Number.isFinite(m.camera[key]))m.camera[key]=defaults.camera[key];
   if(m.camera.fly&&!['x','y','z'].every(k=>Number.isFinite(m.camera.fly[k])))delete m.camera.fly;
   if(m.camera.anchor&&!['x','y','z'].every(k=>Number.isFinite(m.camera.anchor[k])))delete m.camera.anchor;
   if(m.effects!==undefined&&(!Array.isArray(m.effects)||m.effects.some(e=>!record(e))))throw Error('Effets invalides');
   if(m.blocks!==undefined&&(!record(m.blocks)||Object.values(m.blocks).some(c=>!record(c))))throw Error('Blocs invalides');
   m.notes=String(m.notes||'');
  }
  if(!ids.has(world.active))world.active=world.maps[0].id;
  world.log=Array.isArray(world.log)?world.log.filter(v=>record(v)&&typeof v.text==='string'):[];
  world.round=Number.isInteger(world.round)&&world.round>0?world.round:1;
  world.turn=Number.isInteger(world.turn)&&world.turn>=0?world.turn:0;
  return{world,canSave:true,recovered:false};
 }catch{
  let canSave=!raw;
  if(raw)try{const backup=storage.getItem('brumes-v4-recovery');if(backup===raw)canSave=true;else if(!backup){storage.setItem('brumes-v4-recovery',raw);canSave=storage.getItem('brumes-v4-recovery')===raw}}catch{}
  return{world:defaultWorld(),canSave,recovered:true};
 }
}

TYPES.block='Bloc';TYPES.build_door='Porte de construction';

// Frame zero is the front of the actor; angles are relative to its facing.
export function viewerFrame(o,viewer){let p=center(o),a=mod(bearing(viewer.x-p.x,viewer.y-p.y)-(o.facing||0)+(o.frameOffset||0)*Math.PI/180,TAU);return mod(Math.round(a/TAU*(o.frameCount||1)),o.frameCount||1)}
export function viewerImage(o,viewer){return o.frames?.[viewerFrame(o,viewer)]||o.imageId||null}
export function frameLabel(i,n){let degrees=mod(i*360/n,360),names={0:'Face',45:'Trois-quarts droit',90:'Profil droit',135:'Dos trois-quarts droit',180:'Dos',225:'Dos trois-quarts gauche',270:'Profil gauche',315:'Trois-quarts gauche'};return `${i+1} · ${names[degrees]||'Angle intermédiaire'} · ${Math.round(degrees*10)/10}°`}

export function actorCells(o){let w=Math.max(1,Math.min(12,Math.round(o.w||1))),d=Math.max(1,Math.min(12,Math.round(o.d||1)));let cells=[];for(let y=0;y<d;y++)for(let x=0;x<w;x++){let kind=o.occupancy?.[y*w+x]??1;if(kind)cells.push({x,y,kind})}return cells}
export function actorVolumes(o,map){let bottom=elevation(o,map),h=o.bodyHeight||o.height||1.8;return actorCells(o).map(c=>{let lift=c.kind===2?Math.min(o.underClearance??2.5,h):0;return{id:o.id,type:'actor-volume',x:o.x+c.x,y:o.y+c.y,w:1,d:1,facing:0,level:levelOf(o),baseZ:bottom+lift,height:Math.max(.01,h-lift),blocking:true}})}
function footprintParts(actor,x,y,z){if(!actor?.occupancy)return[{actor,x,y}];return actorCells(actor).map(c=>{let lift=c.kind===2?Math.min(actor.underClearance??2.5,actor.bodyHeight||actor.height||1.8):0;return{x:x+c.x,y:y+c.y,actor:{...actor,occupancy:null,w:1,d:1,voxelZ:z+lift,bodyHeight:Math.max(.01,(actor.bodyHeight||actor.height||1.8)-lift),_lift:lift}}})}
function movementObstacles(map,actor,objects){if(!actor?.occupancy)return objects;let ids=new Set(objects.map(o=>o.id));let extra=map.objects.filter(o=>character(o)&&o.id!==actor.id&&!ids.has(o.id)&&levelOf(o)===levelOf(actor));return extra.length?[...objects,...extra.flatMap(o=>actorVolumes(o,map))]:objects}
export function cellFree(map,x,y,actor,objects=obstacles(map,'blocking',levelOf(actor))){objects=movementObstacles(map,actor,objects);if(actor?.occupancy&&!validObject(map,{...actor,x,y}))return false;let z=actor?.voxelZ??terrainHeight(map,x,y);return footprintParts(actor,x,y,z).every(p=>cellFreeSingle(map,p.x,p.y,p.actor,objects)&&(!actor?.occupancy||p.actor._lift>0||!map.blocks||V.surfaceNear(map,p.x,p.y,z,.1)!==undefined))}
export function stepFree(map,from,to,actor,objects=obstacles(map,'blocking',levelOf(actor))){if(!actor?.occupancy)return stepFreeSingle(map,from,to,actor,objects);objects=movementObstacles(map,actor,objects);let z=to.z??actor.voxelZ??terrainHeight(map,to.x,to.y);if(!cellFree(map,to.x,to.y,{...actor,voxelZ:z},objects))return false;return footprintParts(actor,to.x,to.y,z).every(p=>{let dx=p.x-to.x,dy=p.y-to.y,lift=p.actor._lift||0;return stepFreeSingle(map,{...from,x:from.x+dx,y:from.y+dy,z:(from.z??actor.voxelZ??0)+lift},{...to,x:p.x,y:p.y,z:z+lift},p.actor,objects)})}

for(const [id,a] of Object.entries(ASSETS)){PROPS[id]=[a.name,a.w,a.d,a.height,'#ffffff'];TYPES[id]=a.name;}
CATEGORIES.push({id:'kenney-furniture',name:'Mobilier 3D · Kenney',types:Object.keys(ASSETS).filter(k=>ASSETS[k].pack==='furniture-kit')},{id:'kenney-town',name:'Village et nature 3D · Kenney',types:Object.keys(ASSETS).filter(k=>ASSETS[k].pack==='fantasy-town-kit')});

export {ASSETS};
